'use client';

import type { Easing, Variants } from 'motion/react';
import { motion, useAnimation } from 'motion/react';
import type { HTMLAttributes } from 'react';
import { forwardRef } from 'react';
import { useIconAnimation } from '@/lib/use-icon-animation';
import { cn } from '@/lib/utils';

export interface ShoppingCartAdd01IconHandle {
  startAnimation: () => void;
  stopAnimation: () => void;
}

interface ShoppingCartAdd01IconProps extends HTMLAttributes<HTMLDivElement> {
  size?: number;
}

const ADD_DURATION = 0.95;
const ADD_TIMES = [0, 0.1, 0.32, 0.44, 0.56, 0.66, 0.8, 1];
const ADD_EASE: Easing[] = [
  'easeOut',
  [0.33, 1, 0.68, 1],
  'easeOut',
  [0.55, 0, 0.85, 0.35],
  'easeOut',
  'easeInOut',
  'easeInOut',
];

// The plus crouches, hops straight up out of its open corner with a stretch,
// and drops back into place with a squash. Its landing weighs the basket down
// on its wheels, and the basket rebounds. The plus only moves vertically in
// the open corner, so it never crosses the cart.
const cartVariants: Variants = {
  normal: { translateY: 0 },
  animate: {
    translateY: [0, 0, 0, 0, 0, 0.45, -0.15, 0],
    transition: { duration: ADD_DURATION, times: ADD_TIMES, ease: ADD_EASE },
  },
};

const plusVariants: Variants = {
  normal: { translateY: 0, scaleX: 1, scaleY: 1 },
  animate: {
    translateY: [0, 0.3, -2.4, -2.4, 0, 0, 0, 0],
    scaleX: [1, 1.12, 0.9, 1, 1.14, 0.97, 1, 1],
    scaleY: [1, 0.82, 1.12, 1, 0.84, 1.04, 1, 1],
    transition: { duration: ADD_DURATION, times: ADD_TIMES, ease: ADD_EASE },
  },
};

const ShoppingCartAdd01Icon = forwardRef<ShoppingCartAdd01IconHandle, ShoppingCartAdd01IconProps>(
  ({ onMouseEnter, onMouseLeave, className, size = 28, ...props }, ref) => {
    const controls = useAnimation();
    const { handleMouseEnter, handleMouseLeave } = useIconAnimation({
      controls,
      loops: false,
      onMouseEnter,
      onMouseLeave,
      ref,
    });

    return (
      <div
        className={cn(className)}
        onMouseEnter={handleMouseEnter}
        onMouseLeave={handleMouseLeave}
        {...props}
      >
        <svg
          xmlns="http://www.w3.org/2000/svg"
          width={size}
          height={size}
          viewBox="0 0 24 24"
          fill="none"
          overflow="visible"
        >
          <path
            d="M10.5 20.25C10.5 20.6642 10.1642 21 9.75 21C9.33579 21 9 20.6642 9 20.25C9 19.8358 9.33579 19.5 9.75 19.5C10.1642 19.5 10.5 19.8358 10.5 20.25Z"
            stroke="currentColor"
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeWidth="1.5"
          />
          <path
            d="M19 20.25C19 20.6642 18.6642 21 18.25 21C17.8358 21 17.5 20.6642 17.5 20.25C17.5 19.8358 17.8358 19.5 18.25 19.5C18.6642 19.5 19 19.8358 19 20.25Z"
            stroke="currentColor"
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeWidth="1.5"
          />
          <motion.g variants={cartVariants} animate={controls} initial="normal">
            <path
              d="M2 3H2.20664C3.53124 3 4.19354 3 4.6255 3.40221C5.05746 3.80441 5.10464 4.46503 5.19902 5.78626L5.45035 9.30496C5.5924 11.2936 5.66342 12.2879 5.96476 13.0961C6.62531 14.8677 8.08229 16.2244 9.89648 16.757C10.7241 17 11.7267 17 13.7317 17C15.8373 17 16.89 17 17.7417 16.7416C19.6593 16.1599 21.1599 14.6593 21.7416 12.7417C21.9426 12.0793 21.9872 11.299 21.9972 10M12.5 6H5.5"
              stroke="currentColor"
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth="1.5"
            />
            <motion.path
              d="M16 6H22M19 9V3"
              stroke="currentColor"
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth="1.5"
              variants={plusVariants}
              animate={controls}
              initial="normal"
              style={{ transformBox: 'view-box', originX: 19 / 24, originY: 6 / 24 }}
            />
          </motion.g>
        </svg>
      </div>
    );
  }
);

ShoppingCartAdd01Icon.displayName = 'ShoppingCartAdd01Icon';

export { ShoppingCartAdd01Icon };

'use client';

import type { LegacyAnimationControls } from 'motion/react';
import { useReducedMotion } from 'motion/react';
import type {
  ForwardedRef,
  MouseEventHandler,
} from 'react';
import { useCallback, useImperativeHandle, useRef } from 'react';

export interface AnimatedIconHandle {
  startAnimation: () => void;
  stopAnimation: () => void;
}

interface UseIconAnimationOptions {
  controls: LegacyAnimationControls;
  loops?: boolean;
  onMouseEnter?: MouseEventHandler<HTMLDivElement>;
  onMouseLeave?: MouseEventHandler<HTMLDivElement>;
  ref: ForwardedRef<AnimatedIconHandle>;
}

export function useIconAnimation({
  controls,
  loops = false,
  onMouseEnter,
  onMouseLeave,
  ref,
}: UseIconAnimationOptions) {
  const shouldReduceMotion = useReducedMotion();
  const isControlledRef = useRef(false);
  const isPlayingRef = useRef(false);
  const runRef = useRef(0);

  const startAnimation = useCallback(() => {
    if (shouldReduceMotion || isPlayingRef.current) return;

    isPlayingRef.current = true;
    const run = ++runRef.current;
    controls.set('normal');
    void controls.start('animate').then(() => {
      if (runRef.current === run) isPlayingRef.current = false;
    });
  }, [controls, shouldReduceMotion]);

  const stopAnimation = useCallback(() => {
    if (!loops) return;

    runRef.current++;
    isPlayingRef.current = false;
    void controls.start('normal');
  }, [controls, loops]);

  useImperativeHandle(
    ref,
    () => {
      isControlledRef.current = true;
      return { startAnimation, stopAnimation };
    },
    [startAnimation, stopAnimation]
  );

  const handleMouseEnter = useCallback<MouseEventHandler<HTMLDivElement>>(
    (event) => {
      onMouseEnter?.(event);
      if (!isControlledRef.current) startAnimation();
    },
    [onMouseEnter, startAnimation]
  );

  const handleMouseLeave = useCallback<MouseEventHandler<HTMLDivElement>>(
    (event) => {
      onMouseLeave?.(event);
      if (!isControlledRef.current) stopAnimation();
    },
    [onMouseLeave, stopAnimation]
  );

  return { handleMouseEnter, handleMouseLeave };
}
